/* Buildless, local-first game. No external requests, accounts or dependencies. */
(() => {
'use strict';
const DATA=window.FEAST, CH=DATA.chapters, KEY='shkoala.school-secret.v1';
const app=document.getElementById('app'), modalRoot=document.getElementById('modal-root');
const paths={
 arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M18 6 6 18',check:'m5 12 4 4L19 6',
 clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',book:'M4 4h7l1 2 1-2h7v16h-7l-1 1-1-1H4zM12 6v15',
 map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15M15 6v15',sound:'m4 9 4 0 5-4v14l-5-4H4zM17 8c3 2 3 6 0 8M20 5c5 4 5 10 0 14',
 mute:'m4 9 4 0 5-4v14l-5-4H4zM17 9l5 6m0-6-5 6',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 17h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
 teacher:'m2 8 10-5 10 5-10 5zM6 10v7c4 3 8 3 12 0v-7M22 8v8',settings:'M9 3h6l1 4 4 1 2 5-3 3v4l-5 2-3-3H7l-3-5 2-3V7zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
 eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
 pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0M14 10a2 2 0 1 1-4 0 2 2 0 0 1 4 0',
 key:'M14 7a5 5 0 1 1-4 8L3 22l-2-2 7-7M15 6h.01',moon:'M20 15A8 8 0 0 1 9 4a9 9 0 1 0 11 11',
 search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0m-2 5 7 7',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',
 save:'M4 3h14l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8',reset:'M3 10a9 9 0 1 1 1 7M3 3v7h7',
 bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4M12 2v2',spark:'m12 2 2 7 7 3-7 2-2 8-2-8-8-2 8-3z',
 people:'M9 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0M2 21v-4a4 4 0 0 1 8 0v4M20 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0M13 21v-4a4 4 0 0 1 8 0v4',
 trophy:'M7 3h10v7a5 5 0 0 1-10 0zM7 5H3v4c0 4 4 4 4 4m10-8h4v4c0 4-4 4-4 4M12 15v6M8 21h8',
 shield:'m12 2 9 4v7c-2 5-9 9-9 9s-7-4-9-9V6zM8 12l3 3 5-6',chat:'M3 4h18v13H9l-6 4zM7 8h10M7 12h7',home:'m2 11 10-9 10 9M5 9v13h14V9M10 22v-8h4v8',
 file:'M6 2h8l5 5v15H5V2zM14 2v6h5M8 12h8M8 16h8',pause:'M8 5v14M16 5v14',play:'m7 4 14 8-14 8z'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(name,cls='',alt='')=>`<img src="assets/${esc(name)}.webp" class="${cls}" alt="${esc(alt)}" draggable="false">`;
function norm(value){return String(value??'').toLowerCase().replace(/[‘’]/g,"'").replace(/\bwon't\b/g,'will not').replace(/\bcan't\b/g,'cannot').replace(/\baren't\b/g,'are not').replace(/\bisn't\b/g,'is not').replace(/\bhasn't\b/g,'has not').replace(/\bhaven't\b/g,'have not').replace(/\bdidn't\b/g,'did not').replace(/\bi'll\b/g,'i will').replace(/\bi'm\b/g,'i am').replace(/\bwe're\b/g,'we are').replace(/[.!?,:;“”"]/g,'').replace(/\s+/g,' ').trim();}
function accepts(task,value){const answers=Array.isArray(task.answer)?task.answer:[task.answer];return answers.some(a=>norm(a)===norm(value));}
function hash(str){return [...str].reduce((s,c)=>(s*31+c.charCodeAt(0))>>>0,417);}
function shuffle(arr,seed){const a=[...arr];for(let i=a.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;}
function freshChapter(){return{phase:'search',found:[],task:0,answers:{},misses:{},hints:[],assisted:[],production:null,special:0,revealed:false,finished:false};}
function freshState(){return{version:DATA.version,started:false,completed:false,chapter:0,progress:CH.map(freshChapter),inventory:[],settings:{sound:false,large:false,russian:false,motion:false,timer:false},timerLeft:120,seed:Math.floor(Math.random()*999999),updatedAt:null};}
function validateSave(raw){
 if(!raw||raw.version!==DATA.version||!Array.isArray(raw.progress)||(raw.progress.length<1||raw.progress.length>CH.length))throw Error('This save does not match this version of the game.');
 const out=freshState();out.started=!!raw.started;out.completed=false;out.chapter=Math.max(0,Math.min(CH.length-1,Number(raw.chapter)||0));out.seed=Number(raw.seed)||417;
 for(const k of Object.keys(out.settings))out.settings[k]=!!raw.settings?.[k];
 out.inventory=Array.isArray(raw.inventory)?[...new Set(raw.inventory.filter(x=>Object.hasOwn(DATA.items,x)))]:[];
 out.timerLeft=Math.max(0,Math.min(120,Number(raw.timerLeft)||120));
 out.progress=CH.map((c,i)=>{const r=raw.progress[i]||{},p=freshChapter();p.phase=['search','tasks','production','safe','bell','resolved'].includes(r.phase)?r.phase:'search';p.found=Array.isArray(r.found)?r.found.filter(x=>c.hotspots.some(h=>h.id===x)):[];p.task=Math.max(0,Math.min(c.tasks.length-1,Number(r.task)||0));p.special=Math.max(0,Math.min(2,Number(r.special)||0));p.revealed=!!r.revealed;p.finished=!!r.finished;
 c.tasks.forEach(t=>{if(typeof r.answers?.[t.id]==='string'&&r.answers[t.id].length<1500)p.answers[t.id]=r.answers[t.id];const n=Number(r.misses?.[t.id]);if(Number.isFinite(n))p.misses[t.id]=Math.max(0,Math.min(999,n));});
 p.hints=Array.isArray(r.hints)?r.hints.filter(id=>c.tasks.some(t=>t.id===id)):[];p.assisted=Array.isArray(r.assisted)?r.assisted.filter(id=>c.tasks.some(t=>t.id===id)):[];
 if(r.production&&Array.isArray(r.production.values)){p.production={values:r.production.values.slice(0,2).map(x=>String(x).slice(0,3000)),spoken:!!r.production.spoken,checked:!!r.production.checked};}
 return p;});
 out.updatedAt=typeof raw.updatedAt==='string'?raw.updatedAt:null;return out;
}
let storageOK=true;
function loadState(){try{const raw=localStorage.getItem(KEY);return raw?validateSave(JSON.parse(raw)):freshState();}catch{storageOK=false;return freshState();}}
let state=loadState(),screen='home',practiceSnapshot=null,selected='',order=[],feedback='',hintOpen=false,caseTab='evidence',lastFocus=null,modalKind='',toastTimeout=null,timerId=null,timerPaused=false,inputCheckTimer=null,advanceTimer=null;
const current=()=>CH[state.chapter],progress=()=>state.progress[state.chapter];
const isPractice=()=>practiceSnapshot!==null;
function save(){state.updatedAt=new Date().toISOString();if(isPractice())return;try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}}
function grant(ids){for(const id of ids)if(DATA.items[id]&&!state.inventory.includes(id))state.inventory.push(id);}
function totalSolved(){return state.progress.reduce((n,p)=>n+Object.keys(p.answers).length,0);}
function totalMisses(){return state.progress.reduce((n,p)=>n+Object.values(p.misses).reduce((s,v)=>s+v,0),0);}
function toast(message){const el=document.getElementById('toast');clearTimeout(toastTimeout);el.textContent=message;el.classList.add('show');toastTimeout=setTimeout(()=>el.classList.remove('show'),3200);}
function scrollPanel(){if(window.innerWidth<801)document.querySelector('.panel')?.scrollIntoView({behavior:state.settings.motion?'instant':'smooth',block:'start'});}
function resetDraft(){selected='';order=[];feedback='';hintOpen=false;}
function brand(){return`<button class="brand" data-action="home" aria-label="The Midnight Feast home">${img('crest','','Blackthorn Academy crest')}<span><span class="brand-name">The Midnight Feast</span><span class="brand-by">A SCHOOL MYSTERY BY ШКОАЛА</span></span></button>`;}
function topbar(game=false){return`<header class="topbar">${brand()}${game?`<div class="clock-wrap" aria-label="Story time ${clockTime()}">${icon('clock')}<div class="clock-time">${clockTime()}</div><div class="clock-label">31 October 2026<br>Story clock</div></div>`:''}<nav class="nav-actions" aria-label="Game tools">${game?`<button class="nav-link" data-action="casebook" aria-label="Open casebook">${icon('book')}<span class="nav-label">Casebook</span></button><button class="nav-link hide-small" data-action="glossary" aria-label="Open glossary">${icon('chat')}<span class="nav-label">Words</span></button>`:`<button class="nav-link" data-action="how" aria-label="How to play">${icon('help')}<span class="nav-label">How to play</span></button>`}<button class="nav-link" data-action="teacher" aria-label="Teacher’s desk">${icon('teacher')}<span class="nav-label">Teacher’s desk</span></button><span class="nav-pipe"></span><button class="icon-button ${state.settings.sound?'active':''}" data-action="sound" aria-label="${state.settings.sound?'Turn sound off':'Turn sound on'}" title="Sound ${state.settings.sound?'on':'off'}">${icon(state.settings.sound?'sound':'mute')}</button><button class="icon-button" data-action="settings" aria-label="Settings">${icon('settings')}</button></nav></header>`;}
function clockTime(){const c=current(),p=progress();if(state.completed)return'23:59';if(p.phase==='resolved')return c.endTime;if(c.special==='bell'&&p.phase==='bell')return p.special?'23:59':'23:58';if(c.special==='safe'&&p.phase==='safe')return p.special?'23:47':'23:46';return c.time;}
function applySettings(){document.body.classList.toggle('big-text',state.settings.large);document.body.classList.toggle('reduced-motion',state.settings.motion);}
function render(){clearTimeout(inputCheckTimer);clearTimeout(advanceTimer);applySettings();if(state.completed&&screen!=='home')renderEnding();else if(screen==='home')renderHome();else renderGame();syncTimer();scheduleInputAdvance();}
function renderHome(){
 app.innerHTML=`<div class="landing">${topbar()}<main id="main" class="hero"><h1 class="sr-only">The Midnight Feast<span>A Halloween school mystery</span></h1>${img('cover','cover-image','Five teenage friends hide from a vampire headmaster in a candlelit school. The Midnight Feast: a Halloween school mystery.')}<div class="hero-content"><div class="date-tag">31 October · Blackthorn Academy</div><p class="hero-lead">You stayed for the adventure.<br>He stayed for you.</p><p class="hero-copy">Five friends. One vampire headmaster. A hundred-year-old secret.<br>Explore the first two scenes. Find the clues and discover what the headmaster is hiding.</p><div class="button-row"><button class="button primary hero-start" data-action="enter">${state.completed?'Revisit the ending':state.started?'Continue the investigation':'Enter Blackthorn Academy'}${icon('arrow')}</button><button class="button ghost" data-action="how">Meet your team ${icon('people')}</button></div>${state.started?`<p class="hero-resume-note">${state.completed?'Your team escaped. Your casebook is saved.':`Saved at chapter ${state.chapter+1} · ${esc(current().title)}`} <button class="text-link" data-action="new" style="border:0;background:none;color:inherit;font-size:inherit;text-decoration:underline;cursor:pointer">Start a new game</button></p>`:`<p class="hero-resume-note">A2+–B1 · Ages 12–13+ · Play solo or as a team</p>`}</div><div class="hero-bottom"><div class="hero-facts"><div class="hero-fact">${icon('map')} Scenes 01–02</div><div class="hero-fact">${icon('search')} Find · think · escape</div><div class="hero-fact">${icon('clock')} 30–50 minutes</div></div><div class="hero-credit"><a href="https://vk.ru/abc_shkoala" target="_blank" rel="noopener noreferrer">ШКОАЛА<br>для тех, кто учит и учится</a></div></div></main></div>`;
}
function chapterNav(){return`<nav class="chapter-nav" aria-label="Story chapters">${CH.map((c,i)=>{const done=state.progress[i].finished,active=i===state.chapter;return`<button class="chapter-stop ${active?'active':''} ${done?'done':''}" data-action="chapter" data-index="${i}" ${i>0&&!state.progress[i-1].finished&&!done?'disabled':''} ${active?'aria-current="step"':''} aria-label="Chapter ${i+1}: ${esc(c.title)}"><span class="chapter-num">${done?'✓':String(i+1).padStart(2,'0')}</span>${esc(c.short)}</button>`;}).join('')}</nav>`;}
function renderGame(){const c=current(),p=progress();
 app.innerHTML=`<div class="game-shell">${topbar(true)}${isPractice()?`<div class="practice-banner">Teacher preview · Your saved game is preserved.<button data-action="exit-practice">Return to saved game</button></div>`:''}${chapterNav()}<main id="main"><div class="game-heading"><div><div class="chapter-label">Chapter ${String(state.chapter+1).padStart(2,'0')} / ${String(CH.length).padStart(2,'0')}</div><h1>${esc(c.title)}</h1></div><div class="location-label">${icon('pin')}${esc(c.location)}</div></div><div class="game-grid"><section class="visual-column" aria-label="Explore ${esc(c.location)}"><div class="scene-frame" data-action="empty-scene">${renderScene()}</div><div class="explore-controls"><div class="search-progress">${c.hotspots.map(h=>`<span class="search-dot ${p.found.includes(h.id)?'filled':''}"></span>`).join('')}<span>${p.found.length} / ${c.hotspots.length} clues examined</span></div><button class="button ghost compact" data-action="reveal">${icon('eye')}${p.revealed?'Hide clue outlines':'Reveal clue outlines'}</button></div><div class="dialogue"><div class="portrait-wrap">${img(p.phase==='resolved'&&state.chapter===4?'sam':c.speaker,'',DATA.cast[c.speaker].name)}</div><div><div class="dialogue-name">${esc(DATA.cast[c.speaker].name)} <span class="muted">· ${esc(DATA.cast[c.speaker].role)}</span></div><p class="dialogue-text">${esc(p.phase==='resolved'?c.resolution:c.intro)}</p>${p.phase==='resolved'?`<p class="dialogue-extra">${esc(c.nextClue)}</p>`:''}</div></div></section><section class="panel" aria-label="Investigation task" tabindex="-1">${renderPanel()}</section></div>${inventory()}</main><footer class="game-footer"><span>Story time advances between chapters. Take the time you need for English.</span><span class="save-status">${isPractice()?'Teacher preview':storageOK?'Saved on this device':'Use Settings → Export progress to save'} · <a href="https://vk.ru/abc_shkoala" target="_blank" rel="noopener noreferrer">ШКОАЛА</a></span></footer></div>`;
}
function renderScene(){const c=current(),p=progress();let overlay='';
 if(p.phase==='safe'&&p.special===1)overlay=`<div class="safe-overlay"></div><button class="hotspot" style="left:79%;top:63%;width:12%" data-action="take-clapper" aria-label="Take the original bell clapper">${img('clapper')}<span class="hotspot-label">The Founder’s Award</span></button>`;
 if(p.phase==='bell'&&p.special===0)overlay=`<button class="hotspot marker revealed" style="left:54%;top:40%;width:16%" data-action="fit-clapper" aria-label="Fit the clapper to the first school bell"><span class="hotspot-label">Fit the clapper here</span></button>`;
 if(p.phase==='bell'&&p.special===1)overlay=`${img('clapper','bell-restored')}<button class="rope-target" data-action="ring" aria-label="Pull the bell rope"></button>`;
 const activeSpecial=p.phase==='safe'||p.phase==='bell';if(c.id==='mirror')overlay+=`<button class="security-feed" data-action="hotspot" data-index="0" aria-label="Compare camera and mirror"><span class="feed-caption"><span></span> CAMERA 01 · LIVE</span>${img('vale','','Mr Vale on the live camera')}<span class="feed-time">23:00 · WEST CORRIDOR</span></button>`;
 return`${img(c.scene,'scene-backdrop',c.location)}<div class="scene-shade"></div><div class="scene-top"><span class="scene-badge">${icon(activeSpecial?'key':'search')}${activeSpecial?'Use your evidence':'Investigation view'}</span><span class="scene-status">${activeSpecial?'Final action':p.found.length===c.hotspots.length?'All clues examined':'Look closely'}</span></div>${!activeSpecial?c.hotspots.map((h,i)=>`<button class="hotspot ${h.asset?'sprite':'marker'} ${p.found.includes(h.id)?'found':''} ${p.revealed&&!p.found.includes(h.id)?'revealed':''}" style="left:${h.x}%;top:${h.y}%;width:${h.size}%" data-action="hotspot" data-index="${i}" aria-label="${esc(h.label)}" title="${esc(h.label)}">${h.asset?img(h.asset):''}<span class="hotspot-label">${esc(h.label)}</span></button>`).join(''):''}${overlay}<div class="scene-label">${icon('pin')}${esc(c.location)}${c.id==='future'&&p.phase!=='safe'&&p.phase!=='resolved'?' · planning photograph':''}</div>`;
}
function renderPanel(){const c=current(),p=progress();if(p.phase==='search')return renderSearch();if(p.phase==='tasks')return renderTask();if(p.phase==='production')return renderProduction();if(p.phase==='safe')return renderSafe();if(p.phase==='bell')return renderBell();return renderResolved();}
function renderSearch(){const c=current(),p=progress(),all=p.found.length===c.hotspots.length;return`<div class="panel-kicker">${icon('search')} Your investigation<span class="task-counter">Stage 1 / 3</span></div><h2>Every detail matters.</h2><p class="panel-description">${esc(c.searchLead)}</p><div class="objective-card"><div class="eyebrow">The objective</div><p>${esc(c.objective)}</p></div><ul class="check-list">${c.hotspots.map(h=>`<li class="${p.found.includes(h.id)?'checked':''}"><span class="check-circle">${p.found.includes(h.id)?'✓':''}</span>${p.found.includes(h.id)?esc(h.title):'An unread clue is waiting in the scene.'}</li>`).join('')}</ul><button class="button primary full" data-action="start-lock" ${!all?'disabled':''}>${all?'Follow the evidence':'Examine all three clues first'}${icon('arrow')}</button><div class="task-toolbar"><button data-action="russian-help">${icon('help')} Помощь на русском</button><button data-action="glossary">${icon('chat')} Story words</button></div>`;}
function renderTask(){const c=current(),p=progress(),t=c.tasks[p.task],accepted=Object.hasOwn(p.answers,t.id);let input='';const saved=accepted?p.answers[t.id]:'';
 if(t.type==='choice'){input=`<div class="choices" role="group" aria-label="Answer choices">${shuffle(t.options,hash(t.id)+state.seed).map((o,i)=>`<button class="choice ${(!accepted&&selected===o)?'selected':''} ${(accepted&&accepts(t,o))?'accepted':''}" data-action="choice" data-value="${esc(o)}" aria-pressed="${accepted?accepts(t,o):selected===o}" ${accepted?'disabled':''}><span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></button>`).join('')}</div>`;}
 if(t.type==='input'){input=`<label for="answer-input" class="input-label">Type the missing word or phrase. Correct answers continue automatically.</label><input id="answer-input" type="text" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Your answer…" value="${esc(accepted?saved:selected)}" ${accepted?'readonly':''} aria-describedby="task-prompt">`;}
 if(t.type==='order'){const choices=shuffle(t.words.map((w,i)=>({w,i})),hash(t.id)+state.seed);input=`<div class="sentence-build" role="group" aria-label="Your sentence">${accepted?`<span>${esc(saved)}</span>`:order.map(i=>`<button type="button" class="word-token" data-action="remove-word" data-index="${i}" aria-label="Remove ${esc(t.words[i])}">${esc(t.words[i])}</button>`).join('')}</div>${!accepted?`<div class="word-bank" role="group" aria-label="Words to choose">${choices.map(({w,i})=>`<button type="button" class="word-token ${order.includes(i)?'used':''}" data-action="word" data-index="${i}" ${order.includes(i)?'disabled':''}>${esc(w)}</button>`).join('')}</div>`:''}`;}
 const end=p.task===c.tasks.length-1;return`<div class="panel-kicker">${esc(t.tag)}<span class="task-counter">${p.task+1} / ${c.tasks.length} decisions</span></div><div class="task-progress" aria-label="${p.task+1} of ${c.tasks.length}"><span style="width:${(p.task+1)/c.tasks.length*100}%"></span></div>${timerMarkup(t)}${t.context?`<p class="task-context">${esc(t.context)}</p>`:''}${t.diagram?roomModel(t.diagram):''}<p id="task-prompt" class="task-prompt">${esc(t.prompt)}</p><form class="task-form" id="task-form">${input}${accepted?`<div class="feedback" role="status"><strong>${icon('check')} Evidence confirmed.</strong>${esc(t.explanation)}${t.type==='input'?'<div class="small">Opening the next task… Press Enter to continue now.</div>':''}${p.assisted.includes(t.id)?'<div class="small">Model used · revisit this form with your teacher.</div>':''}</div><div class="task-actions"><button class="button primary" type="button" data-action="next-task">${end?'Your team’s turn':'Continue'}${icon('arrow')}</button></div>`:`${feedback?`<div class="feedback error" role="alert"><strong>Not quite yet.</strong>${esc(t.hint)}<div class="small">You can try again. The story clock has not moved.</div></div>`:''}${hintOpen?`<div class="hint-box">${icon('help')} ${esc(t.hint)}</div>`:''}<div class="task-actions"><button type="button" class="button primary" data-action="check-answer">Check & continue ${icon('check')}</button><button type="button" class="button ghost" data-action="hint" aria-label="Show hint">${icon('help')} Hint</button></div>`}</form><div class="task-toolbar"><button data-action="chapter-evidence">${icon('book')} Read the clues</button>${!accepted&&(p.misses[t.id]||0)>=2?`<button data-action="model-task">${icon('eye')} Use a model</button>`:`<button data-action="russian-help">${icon('help')} Помощь</button>`}</div>`;}
function roomModel(kind){
 const object=(asset,left,top,w,h=55,style='')=>`<img src="assets/${asset}.webp" alt="${asset.replaceAll('-',' ')}" class="model-object model-highlight" style="left:${left}%;top:${top}%;width:${w}%;height:${h}px;${style}">`;
 let content='<div class="model-desk" aria-label="desk"></div><span class="model-label" style="left:43%;top:60%;z-index:5">desk</span>';
 if(kind==='on')content+=object('candle',45,28,13,56,'z-index:4')+'<span class="model-label" style="left:59%;top:35%">candle</span>';
 if(kind==='in')content=object('jar',38,20,30,132,'opacity:.75;z-index:1')+object('gold-key',45,41,17,70,'z-index:2')+'<span class="model-label" style="left:70%;top:48%">glass jar</span>';
 if(kind==='under')content+=object('blue-book',37,70,15,43,'z-index:4')+object('diary',51,70,15,43,'z-index:4')+'<span class="model-label" style="left:73%;top:78%">two books</span>';
 if(kind==='next to')content=object('mask',19,38,32,70)+object('jar',58,22,22,100)+'<span class="model-label" style="left:28%;top:82%">mask</span><span class="model-label" style="left:60%;top:82%">jar</span>';
 if(kind==='behind')content+=object('photo',36,25,21,66,'z-index:1')+object('candle',44,29,14,58,'z-index:5')+'<span class="model-label" style="left:13%;top:28%">photograph</span><span class="model-label" style="left:60%;top:42%">candle</span>';
 if(kind==='above')content+=img('crest','model-portrait','portrait on the wall')+'<span class="model-label" style="left:61%;top:26%">portrait</span>';
 if(kind==='in front of')content+=object('chest',38,67,26,66,'z-index:5')+'<span class="model-label" style="left:64%;top:86%">chest</span>';
 if(kind==='opposite')content='<div class="model-door left" aria-label="left door"></div><div class="model-door right" aria-label="right door"></div><div class="model-room-line"></div><span class="model-label" style="left:40%;top:80%">across the room</span>';
 return`<div class="room-model" role="img" aria-label="Room model reference picture. Use the positions shown to complete the description."><span class="model-caption">The reading-table model · look closely</span>${content}</div>`;
}
function renderProduction(){const c=current(),p=progress(),saved=p.production;return`<div class="panel-kicker">Make it your own<span class="task-counter">Stage 3 / 3</span></div><h2>Your team’s turn.</h2><p class="panel-description">Write two short answers, or say both aloud. Open answers are checked by you and your teacher — they are not automatically graded.</p>${saved?`${c.production.map((q,i)=>`<div class="model-answer"><div class="eyebrow">One possible answer · ${i+1}</div>${esc(q.model)}</div>`).join('')}<p class="small muted">Different answers can be correct. Check the form, meaning and story evidence.</p><label class="checkbox-row"><input id="self-check" type="checkbox" ${saved.checked?'checked':''}>We checked our two answers against the examples or with our teacher.</label><button class="button primary full" data-action="finish-production">${c.special==='safe'?'Go to the safe':c.special==='bell'?'Restore the first bell':'Close this chapter'}${icon('arrow')}</button>`:`<form id="production-form" class="production">${c.production.map((q,i)=>`<label for="production-${i}"><span class="eyebrow">${i+1} · Speak or write</span><br>${esc(q.prompt)}<textarea id="production-${i}" placeholder="Your team’s answer…" maxlength="3000"></textarea></label>`).join('')}<label class="checkbox-row"><input id="spoken" type="checkbox">We said both answers aloud.</label><button class="button primary full" type="button" data-action="save-production">Save our answers ${icon('book')}</button><p class="small muted" id="production-error" role="status"></p></form>`}`;}
function renderSafe(){const p=progress();if(p.special===0)return`<div class="panel-kicker">The office safe<span class="task-counter">23:46</span></div><h2>The key is real.</h2><p class="panel-description">Sam gave you the safe key at 23:29. You entered during the speech, hid when Vale returned early, and waited until he left again. Now take the relic your evidence identified.</p><div class="safe-choice">${img('gold-key','','Sam’s safe key')}<div><h3>Sam’s key</h3><p>The safe key, not Vale’s spare door key.</p></div></div><button class="button primary full" data-action="unlock-safe">Use the safe key ${icon('key')}</button>`;if(p.special===1)return`<div class="panel-kicker">The safe is open<span class="task-counter">23:47</span></div><h2>The “award” is waiting.</h2><p class="panel-description">The sketch in Sam’s diary matches the metal relic inside. Take the <strong>original bell clapper</strong> from the open safe in the picture.</p><div class="objective-card"><div class="eyebrow">Use what you learned</div><p>Click the Founder’s Award inside the safe.</p></div><button class="button full" data-action="take-clapper">Take the Founder’s Award ${icon('arrow')}</button><p class="small muted" style="margin-top:15px">You can also choose the object directly in the scene.</p>`;return`<div class="panel-kicker">The final proof<span class="task-counter">23:48</span></div><h2>He chose you.</h2><div class="safe-choice">${img('clapper','','The bell clapper')}<div><h3>The Founder’s Award</h3><p>In your inventory. The first bell can be restored.</p></div></div><p class="panel-description">Below the clapper: five invitations printed on <strong>24 October</strong> and the anonymous challenge draft, signed <strong>E. Vale</strong>. Your names came from the registration form. This was his plan all along.</p><button class="button primary full" data-action="close-special">Meet Sam and get to the junction ${icon('arrow')}</button>`;}
function renderBell(){const p=progress();return`<div class="panel-kicker">The first school bell<span class="task-counter">Final action</span></div><div class="bell-state">${p.special?'23:59':'23:58'}</div><h2>${p.special?'A living hand. One sound.':'You made the right choice.'}</h2><p class="panel-description">${p.special?'The original clapper is secure. Below you, Vale begins calling the five names. Ring the bell before midnight.':'The empty library corridor took six minutes. One minute remains to fit the clapper. The heavy bell is waiting above you.'}</p><div class="safe-choice">${img('clapper')}<div><h3>${p.special?'Clapper restored':'The original clapper'}</h3><p>${p.special?'The first school bell is ready.':'Use the relic and secure the fixing pin.'}</p></div></div><button class="button primary full" data-action="${p.special?'ring':'fit-clapper'}">${p.special?'Ring the first school bell':'Fit the clapper'}${icon(p.special?'bell':'key')}</button><p class="small muted" style="margin-top:15px">${p.special?'You can also pull the highlighted rope in the scene.':'You can also click the centre of the bell in the scene.'}</p>`;}
function renderResolved(){const c=current(),p=progress(),hasNext=state.chapter<CH.length-1;return `<div class="panel-kicker">Scene ${String(state.chapter+1).padStart(2,'0')} complete ${icon('check')}</div><h2>${hasNext?'The school has changed.':'The reflection is missing.'}</h2><p class="panel-description">You examined ${p.found.length} clues, solved ${c.tasks.length} language decisions and checked your own two answers.</p><p class="resolution-quote">${esc(c.nextClue)}</p>${hasNext?`<button class="button primary full" data-action="next-chapter">Enter scene 2: The man in the mirror ${icon('arrow')}</button>`:`<p class="panel-description">You escape into the old library. On the door, a note reads: FIND THE SCHOOL CHARTER.</p><div class="separator"></div><div class="eyebrow">To be continued · Scene 03</div><h3 style="margin:9px 0 22px">The forgotten library</h3><button class="button primary full" data-action="casebook">Review your casebook ${icon('book')}</button>`}<div class="task-toolbar"><button data-action="casebook">${icon('book')} Review the evidence</button><button data-action="export">${icon('save')} Export progress</button><button data-action="home">${icon('home')} Back to the cover</button></div>`;}

function inventory(){return`<aside class="inventory" aria-label="Inventory"><div class="inventory-label">Your<br>evidence</div><div class="inventory-items">${state.inventory.length?state.inventory.map(id=>`<button class="inventory-item" data-action="item" data-id="${id}" aria-label="Examine ${esc(DATA.items[id].name)}" title="${esc(DATA.items[id].name)}">${img(DATA.items[id].asset)}</button>`).join(''):'<span class="inventory-empty">Useful objects and evidence will appear here.</span>'}</div><button class="button" data-action="casebook">${icon('book')} Open casebook</button></aside>`;}
function openModal(title,html,{wide=false,kicker='Blackthorn Academy',kind=''}={}){if(!modalRoot.innerHTML)lastFocus=document.activeElement;clearTimeout(inputCheckTimer);clearTimeout(advanceTimer);modalKind=kind;modalRoot.innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-head"><div><div class="eyebrow">${kicker}</div><h2 id="modal-title">${esc(title)}</h2></div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-content">${html}</div></section></div>`;document.body.style.overflow='hidden';modalRoot.querySelector('.modal').focus();pauseTimer();}
function closeModal(){modalRoot.innerHTML='';modalKind='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();lastFocus=null;syncTimer();scheduleInputAdvance();}
function openHotspot(index){const c=current(),p=progress(),h=c.hotspots[index];if(!h)return;const isNew=!p.found.includes(h.id);if(isNew){p.found.push(h.id);if(h.inventory)grant([h.inventory]);save();sfx('clue');render();}openDocument(state.chapter,index,isNew);}
function openDocument(ci,hi,isNew=false){const c=CH[ci],h=c?.hotspots[hi];if(!h)return;openModal(h.title,`<article class="document">${h.body}</article><div class="document-bottom"><span class="found-tag">${icon('check')}${isNew?'Added to your casebook':'Evidence examined'}</span><button class="button primary" data-action="close-modal">Keep investigating ${icon('arrow')}</button></div>`,{kicker:`Evidence · ${c.location}`,kind:'evidence'});}
function openItem(id){const it=DATA.items[id];if(!it||!state.inventory.includes(id))return;openModal(it.name,`<div class="safe-choice">${img(it.asset,'',it.name)}<div><h3>${esc(it.name)}</h3><p>${esc(it.detail)}</p></div></div><button class="button primary" data-action="close-modal">Back to the investigation ${icon('arrow')}</button>`,{kicker:'Your inventory',kind:'item'});}
function openCasebook(tab=caseTab){caseTab=tab;const tabs=[['evidence','Documents'],['rules','The rules'],['answers','Our answers'],['story','Story so far']];let html='';
 if(tab==='evidence'){const found=[];state.progress.forEach((p,ci)=>p.found.forEach(id=>{const hi=CH[ci].hotspots.findIndex(h=>h.id===id);if(hi>=0)found.push({ci,hi,h:CH[ci].hotspots[hi]});}));html=found.length?`<div class="evidence-grid">${found.map(({ci,hi,h})=>`<button class="evidence-card" data-action="case-doc" data-chapter="${ci}" data-index="${hi}">${img(h.asset||'note')}<strong>${esc(h.title)}</strong><small>Chapter ${ci+1} · ${esc(CH[ci].location)}</small></button>`).join('')}</div>`:'<div class="empty-state">Your casebook is empty. Examine objects in a scene to collect evidence.</div>';}
 if(tab==='rules')html=state.inventory.includes('charter')?`<div class="rule-list"><div class="rule">The crypt opens every Halloween at 23:00. The school boundary then closes. Ordinary exits cannot take living visitors outside.</div><div class="rule">Vale and his guests cannot harm living visitors before midnight. Afterwards, the protection ends.</div><div class="rule">A living person must restore the first bell with its original clapper and ring it before midnight. The sound ends the feast, returns Vale to the crypt and frees his former pupils.</div><div class="rule">The clapper also opens the crypt. It cannot be destroyed. A camera records vampires, but a mirror does not reflect them.</div></div>`:'<div class="empty-state">The school charter will explain the rules. Keep investigating.</div>';
 if(tab==='answers'){const entries=state.progress.flatMap((p,i)=>p.production?[{p,c:CH[i],i}]:[]);html=entries.length?entries.map(({p,c,i})=>`<div class="team-log-entry"><div class="eyebrow">Chapter ${i+1} · ${esc(c.title)}</div>${c.production.map((q,j)=>`<p class="prompt">${esc(q.prompt)}</p>${p.production.values[j]?.trim()?`<p>${esc(p.production.values[j])}</p>`:'<p><em>Discussed aloud with the team.</em></p>'}`).join('')}<em>${p.production.checked?'Compared with examples or checked by the teacher.':'Waiting for your self-check.'}</em></div>`).join(''):'<div class="empty-state">Your own sentences will be saved here after each chapter.</div>';}
 if(tab==='story')html=`<div class="timeline">${state.progress.map((p,i)=>p.finished?`<div class="timeline-row"><strong>${CH[i].endTime}</strong><div><div class="eyebrow">${esc(CH[i].title)}</div>${esc(CH[i].resolution)}</div></div>`:'').join('')||'<div class="empty-state">Finish the first chapter to start your story record.</div>'}</div>`;
 openModal('The casebook',`<div class="case-tabs" role="tablist">${tabs.map(([id,label])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-action="case-tab" data-id="${id}">${label}</button>`).join('')}</div>${html}`,{wide:true,kicker:'Read · compare · verify',kind:'casebook'});
}
function openChapterEvidence(){const c=current(),p=progress();openModal('Clues from this chapter',`<div class="evidence-grid">${c.hotspots.map((h,i)=>p.found.includes(h.id)?`<button class="evidence-card" data-action="case-doc" data-chapter="${state.chapter}" data-index="${i}">${img(h.asset||'note')}<strong>${esc(h.title)}</strong><small>Read this document</small></button>`:'').join('')}</div>`,{kicker:c.title,kind:'evidence-list'});}
function openHow(){openModal('Five friends. Stay together.',`<p>You are part of a team that stayed after a school Halloween party. The headmaster has other plans. Read the story in English, examine each scene and use the evidence to escape.</p><div class="character-grid">${Object.entries(DATA.cast).slice(0,5).map(([id,c])=>`<div class="character-card">${img(id,'',c.name)}<strong>${c.name}</strong><small>${c.role}</small></div>`).join('')}</div><div class="how-grid"><div class="how-step"><div class="eyebrow">01 · Explore</div><h3>Look closely.</h3><p>Click objects and diamond markers in each scene. Read all three clues. Use “Reveal clue outlines” if you need help finding them.</p></div><div class="how-step"><div class="eyebrow">02 · Investigate</div><h3>Check the evidence.</h3><p>Choose answers, type missing words and build sentences. Mistakes give hints. The story clock waits while you work on your English.</p></div><div class="how-step"><div class="eyebrow">03 · Speak</div><h3>Use your own words.</h3><p>Write two answers or say them aloud. Compare them with the examples or check with your teacher. These open answers are not automatically graded.</p></div><div class="how-step"><div class="eyebrow">04 · Remember</div><h3>Keep a casebook.</h3><p>Reopen clues, objects and your sentences at any time. Progress saves on this device. Export a save file to continue elsewhere.</p></div></div><div class="separator"></div><p class="small muted">Совет учителю: игру можно пройти командой на экране или распределить роли. При переключении глав сюжетное время меняется автоматически. На языковые задания реального ограничения времени нет.</p><button class="button primary" data-action="how-enter">${state.started?'Back to the investigation':'Start the investigation'}${icon('arrow')}</button>`,{wide:true,kicker:'How to play · A2+–B1',kind:'how'});}
const glossary=[['feast','a large, special meal','пир, праздничное застолье'],['former student','someone who studied here before','бывший ученик, выпускник'],['headmaster','the person in charge of the school','директор школы'],['clue','a detail that helps solve a mystery','улика, подсказка'],['evidence','facts that support an explanation','данные, доказательства'],['crypt','an underground room, often below an old building','склеп'],['boundary','a line you cannot cross','граница'],['charter','a document with the school’s important rules','устав'],['founder','the person who started the school','основатель'],['oath','a serious promise','клятва'],['clapper','the metal part inside a bell that makes it ring','язык колокола'],['safe','a strong, locked box for valuable things','сейф'],['spell','magic that changes or controls something','заклятие'],['disguise','clothes or a new appearance that hide your identity','маскировка'],['reflection','the image you see in a mirror','отражение'],['relic','an old object with special importance','реликвия'],['appointment','a meeting agreed for a specific time','назначенная встреча'],['arrangement','a plan agreed with someone','договорённость'],['fixing pin','a metal piece that holds another part in place','крепёжный штифт'],['junction','a place where routes meet','развилка']];
function openGlossary(){openModal('Words for the investigation',`<div class="glossary-grid">${glossary.map(([a,b,c])=>`<div class="glossary-entry"><strong>${a}</strong><span>${b}</span><br><span class="muted">${c}</span></div>`).join('')}</div>`,{wide:true,kicker:'English · Русский',kind:'glossary'});}
const ruHelp=[
 ['Найдите маску, карточку челленджа и часы с расписанием. Привычки сотрудников не гарантируют, что сегодня они поступят так же: проверьте камеру.','Present Simple — привычки. Usually / often / sometimes стоят перед смысловым глаголом; после be: He is never late. In — месяц; on — день и дата; at — время. Half past = 30 минут; quarter past = 15 минут; quarter to = без четверти.'],
 ['Сравните обычный вечер с происходящим сейчас. Камера снимает вампиров, зеркало их не отражает. Рассмотрите портрет и школьное объявление.','Present Simple — состояние или привычка. Present Continuous — действие сейчас. I think — мнение; I am thinking — обдумываю. He has a key — обладание; He is having a meeting — действие. Know, need, recognise здесь описывают состояния.'],
 ['Найдите фотографию, устав и макет комнаты. В каждом задании с предлогом появится наглядная схема. Важны все правила из устава.','There is — единственное число; there are — множественное. In — внутри; on — на поверхности; under — под; above — выше, без контакта; behind — за; in front of — перед; next to — рядом; opposite — напротив.'],
 ['Вы играете роль Alex Grey из театрального клуба. По четырём совпадениям определите автора записки, затем сверьте предупреждение с уставом.','Сочетания: curious about, interested in, scared of, good at, worried about, proud of, excited about, bad at. Одного совпадения имени недостаточно для вывода.'],
 ['Восстановите ночь 1926 года. Определите, зачем директору реликвия и почему Сэм не может восстановить колокол.','Past Continuous — действие в процессе: was/were + V-ing. Past Simple — отдельное законченное событие: V2. While часто соединяет два параллельных процесса; when может вводить событие на их фоне. После did используем начальную форму глагола.'],
 ['Старый дневник объясняет назначение предмета, но его нынешнее место нужно подтвердить сегодняшней записью с камеры.','Present Perfect: have/has + V3. For + длительность; since + начальная точка. Already обычно между have/has и V3; yet — в конце вопроса/отрицания. Точное законченное время требует Past Simple. I already have — обладание; I have already found — результат.'],
 ['По программе, карточке встречи и записке Сэма выберите окно для проникновения. Если обстоятельства меняются, реагируйте вместе и сохраняйте обещание.','Present Simple — расписание. Present Continuous — подтверждённая договорённость. Going to — принятое решение или прогноз по видимым признакам. Will — решение в момент речи, помощь, обещание, предположение. В свободном ответе возможны разные формы, если контекст их оправдывает.'],
 ['Сейчас 23:52. На установку языка колокола нужна 1 минута. Сравнивайте и длительность пути, и опасность. Звонок должен прозвучать до 00:00.','Прилагательное описывает предмет; наречие — действие. Quiet → quietly, careful → carefully; good → well; fast → fast. Сравнения: safer, more dangerous, the fastest; more quietly, more carefully, better.']
];
function openRussianHelp(){const [a,b]=ruHelp[state.chapter];openModal('Помощь по главе',`<h3>Что нужно сделать</h3><p>${a}</p><h3>Как работает грамматика</h3><p>${b}</p><p class="small muted">Подсказка помогает разобраться. Готовые ответы — на учительском столе.</p>`,{kicker:current().title,kind:'ru'});}
function openTeacher(){openModal('The teacher’s desk',`<div class="teacher-warning">Spoilers ahead. Teacher preview opens a separate practice session and preserves your saved game.</div><p class="chapter-summary"><strong>A2+–B1 · 12–13+ · 2 linked scenes · ${CH.reduce((n,c)=>n+c.tasks.length,0)} checked decisions · 4 open responses.</strong><br>Suggested pace: 30–50 minutes for the two scenes, with grammar already introduced. Keep the real timer off for teaching; the story clock advances only with the plot.</p><div class="button-row"><a class="button primary" href="teacher-guide.html" target="_blank">${icon('file')} Printable teacher guide & keys</a><button class="button" data-action="export">${icon('save')} Export this save</button></div><h3>Preview a chapter</h3><div class="teacher-chapters">${CH.map((c,i)=>`<button class="teacher-chapter" data-action="practice" data-index="${i}"><span>Chapter ${i+1} · ${c.time}</span><strong>${esc(c.title)}</strong><small>${[...new Set(c.tasks.map(t=>t.tag))].join(' · ')}</small></button>`).join('')}</div><div class="teacher-keys"><h3>Answer keys & rationale</h3>${CH.map((c,i)=>`<details><summary>${i+1}. ${esc(c.title)} · ${c.tasks.length} decisions</summary><ol>${c.tasks.map(t=>`<li>${esc(t.prompt)}<br><strong>${esc(Array.isArray(t.answer)?t.answer.join(' / '):t.answer)}</strong><p>${esc(t.explanation)}</p></li>`).join('')}</ol><p class="small muted">Open responses require teacher or peer review. Examples:<br>${c.production.map(q=>esc(q.model)).join('<br>')}</p></details>`).join('')}</div>`,{wide:true,kicker:'Teaching · rehearsal · answers',kind:'teacher'});}
function openSettings(){openModal('Make the game work for you',`<div class="settings-grid">${[['large','Large classroom text','Larger tasks, choices and dialogue for a projector.'],['motion','Reduce motion','Turn off interface animation.']].map(([id,label,desc])=>`<div class="setting"><div><strong>${label}</strong><small>${desc}</small></div><button class="toggle" data-action="setting" data-id="${id}" role="switch" aria-checked="${state.settings[id]}" aria-label="${label}"></button></div>`).join('')}</div><div class="separator"></div><h3>Your progress</h3><p class="small muted">Progress saves in this browser on this device. Export a JSON save to move to another device. The game does not send your answers anywhere.</p><div class="button-row"><button class="button" data-action="export">${icon('download')} Export progress</button><button class="button" data-action="import">${icon('save')} Import progress</button><button class="button danger" data-action="new">${icon('reset')} New game</button></div><input id="import-file" type="file" accept=".json,application/json" class="sr-only"><div class="separator"></div><button class="button ghost" data-action="how">${icon('help')} How to play / Как играть</button>`,{kicker:'Display · pace · saved game',kind:'settings'});}
function exportProgress(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Midnight_Feast_Progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress exported. Keep the JSON file to continue elsewhere.');}
function confirmNew(){openModal('Start a new investigation?',`<p class="reset-note">This replaces the game saved on this device. You can export your current progress first.</p><div class="button-row"><button class="button" data-action="export">${icon('save')} Export first</button><button class="button danger" data-action="confirm-new">Start a new game</button><button class="button ghost" data-action="close-modal">Keep current game</button></div>`,{kicker:'Saved progress',kind:'reset'});}
function enterPractice(i){if(!isPractice())practiceSnapshot=state;const prefs=state.settings;state=freshState();state.settings={...prefs};state.started=true;state.chapter=i;CH.slice(0,i).forEach((c,j)=>{state.progress[j].finished=true;grant(c.reward);});screen='game';closeModal();resetDraft();render();window.scrollTo({top:0});toast('Teacher preview started. Your saved game is preserved.');}
function exitPractice(){if(!practiceSnapshot)return;state=practiceSnapshot;practiceSnapshot=null;screen=state.started?'game':'home';resetDraft();closeModal();render();window.scrollTo({top:0});}
function checkTask(value){const p=progress(),t=current().tasks[p.task];if(Object.hasOwn(p.answers,t.id))return;const answer=value??(t.type==='order'?order.map(i=>t.words[i]).join(' '):t.type==='input'?document.getElementById('answer-input')?.value:selected);if(!String(answer||'').trim()){toast(t.type==='order'?'Choose the words to build a sentence.':'Choose or type your answer first.');return;}selected=String(answer);if(accepts(t,answer)){p.answers[t.id]=String(answer);feedback='';sfx('correct');}else{p.misses[t.id]=(p.misses[t.id]||0)+1;feedback='wrong';sfx('wrong');}save();render();if(t.type==='input'&&!Object.hasOwn(p.answers,t.id)){const input=document.getElementById('answer-input');input?.focus({preventScroll:true});input?.select();}}
function scheduleInputAdvance(){clearTimeout(advanceTimer);if(screen!=='game'||state.completed||modalRoot.innerHTML)return;const p=progress(),t=current().tasks[p.task];if(p.phase!=='tasks'||t.type!=='input'||!Object.hasOwn(p.answers,t.id))return;const snapshot=state,chapter=state.chapter,taskIndex=p.task;advanceTimer=setTimeout(()=>{if(state===snapshot&&screen==='game'&&!modalRoot.innerHTML&&state.chapter===chapter&&progress().phase==='tasks'&&progress().task===taskIndex)nextTask();},1200);}
function nextTask(){const p=progress(),c=current();if(!Object.hasOwn(p.answers,c.tasks[p.task].id))return;if(p.task<c.tasks.length-1)p.task++;else p.phase='production';resetDraft();save();render();document.getElementById('answer-input')?.focus({preventScroll:true});scrollPanel();}
function submitProduction(){const vals=[0,1].map(i=>document.getElementById(`production-${i}`)?.value.trim()||''),spoken=!!document.getElementById('spoken')?.checked;const enough=vals.every(v=>v.split(/\s+/).filter(Boolean).length>=3);if(!spoken&&!enough){document.getElementById('production-error').textContent='Write a short answer for both prompts, or say both aloud and tick the box.';return;}progress().production={values:vals,spoken,checked:false};save();sfx('clue');render();scrollPanel();}
function finishProduction(){if(!document.getElementById('self-check')?.checked){toast('Compare your answers with the examples or your teacher, then tick the self-check.');return;}const p=progress(),c=current();p.production.checked=true;if(c.special==='safe'){p.phase='safe';p.special=0;grant(['key']);}else if(c.special==='bell'){p.phase='bell';p.special=0;}else completeChapter();save();render();scrollPanel();}
function completeChapter(){const p=progress();p.finished=true;p.phase='resolved';grant(current().reward);save();sfx('chapter');}
function nextChapter(){if(!progress().finished)return;if(state.chapter<CH.length-1){state.chapter++;resetDraft();save();render();window.scrollTo({top:0,behavior:'smooth'});}}
function ringBell(){const p=progress();if(current().special!=='bell'||p.phase!=='bell'||p.special!==1)return;pauseTimer();state.completed=true;p.finished=true;p.phase='resolved';save();sfx('bell');closeModal();const flash=document.createElement('div');flash.className='ring-flash';document.body.append(flash);screen='ending';setTimeout(()=>{render();window.scrollTo({top:0});},450);setTimeout(()=>flash.remove(),1900);}
function renderEnding(){const clues=state.progress.reduce((n,p)=>n+p.found.length,0),own=state.progress.reduce((n,p)=>n+(p.production?2:0),0);app.innerHTML=`<div class="ending">${topbar()}${isPractice()?`<div class="practice-banner">Teacher preview<button data-action="exit-practice">Return to saved game</button></div>`:''}<main id="main"><div class="ending-hero"><div class="ending-art">${img('sam','ending-reflection','Sam’s reflection')}${img('sam','','Sam is human again')}<div class="ending-quote">“I can see myself.”</div></div><div class="ending-story"><div class="eyebrow">23:59 · The spell is broken</div><h1>${DATA.ending.title}</h1>${DATA.ending.paragraphs.map(p=>`<p class="${p.startsWith('“')?'quote':''}">${esc(p)}</p>`).join('')}<div class="ending-stats"><div><strong>${totalSolved()}</strong><span>Language decisions</span></div><div><strong>${clues}</strong><span>Clues examined</span></div><div><strong>${own}</strong><span>Your own responses</span></div></div><div class="button-row"><button class="button primary" data-action="casebook">Review your casebook ${icon('book')}</button><button class="button" data-action="debrief">One last conversation ${icon('chat')}</button></div></div></div><div class="epilogue">${icon('file')}<div><div class="eyebrow">The next school morning</div><p>THE HEADMASTER WILL NOT BE RETURNING.<br>PLEASE DO NOT OPEN THE BASEMENT.</p></div></div><div style="text-align:center;padding:0 20px 40px"><button class="button ghost" data-action="export">${icon('download')} Save the investigation</button><a class="button ghost" href="https://vk.ru/abc_shkoala" target="_blank" rel="noopener noreferrer">ШКОАЛА — для тех, кто учит и учится ${icon('arrow')}</a></div></main></div>`;}
function openDebrief(){openModal('What will happen next?',`<p>You escaped by checking evidence and working as a team. Discuss the questions. More than one answer can work.</p><ol style="line-height:2.2;font-size:15px"><li>Which early clue became important at the end?</li><li>What was Sam doing when he saw Vale open the crypt?</li><li>How has Sam’s life changed?</li><li>Why was the library corridor safer than the main hall?</li><li>What are the five friends going to do now?</li><li>What do you think will happen if someone opens the basement?</li></ol><div class="objective-card"><div class="eyebrow">A final team challenge</div><p>Retell the story in four sentences. Use the grammar from the two scenes.</p></div>`,{kicker:'Speaking · reflect · predict',kind:'debrief'});}
let audioCtx=null,ambient=[];
function ensureAudio(){if(!state.settings.sound)return null;try{if(!audioCtx){audioCtx=new (window.AudioContext||window.webkitAudioContext)();}if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx;}catch{return null;}}
function startAmbient(){const ctx=ensureAudio();if(!ctx||ambient.length)return;[73.42,110,146.83].forEach((hz,i)=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=hz;gain.gain.value=.009-i*.002;osc.connect(gain);gain.connect(ctx.destination);osc.start();ambient.push({osc,gain});});}
function stopAmbient(){ambient.forEach(({osc})=>{try{osc.stop();}catch{}});ambient=[];}
function sfx(type){const ctx=ensureAudio();if(!ctx)return;const now=ctx.currentTime;const sounds={clue:[523,784],correct:[440,659,880],wrong:[196,185],chapter:[392,494,587],bell:[146.83,293.66,436,587.32,741,1030]};(sounds[type]||sounds.clue).forEach((hz,i)=>{const osc=ctx.createOscillator(),g=ctx.createGain(),start=now+(type==='bell'?0:i*.09),duration=type==='bell'?5.5:.42;osc.type='sine';osc.frequency.value=hz;g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(type==='bell'?.1/(i+1):.045,start+.015);g.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(g);g.connect(ctx.destination);osc.start(start);osc.stop(start+duration+.1);});}
function toggleSound(){state.settings.sound=!state.settings.sound;if(state.settings.sound){startAmbient();sfx('clue');}else stopAmbient();save();render();toast(state.settings.sound?'Sound on. Use the speaker button to mute.':'Sound off.');}
function timerWanted(){return state.settings.timer&&screen==='game'&&!state.completed&&current().id==='bell'&&progress().phase==='tasks'&&progress().task===current().tasks.length-1&&!progress().answers[current().tasks.at(-1).id];}
function timerMarkup(t){if(t.id!=='8-14'||!state.settings.timer)return'';return`<div class="final-timer"><span>Optional team timer</span><strong id="timer-value">${timerText()}</strong><button class="icon-button" style="height:25px;width:25px" data-action="pause-timer" aria-label="${timerPaused?'Resume':'Pause'} timer">${icon(timerPaused?'play':'pause')}</button></div>`;}
function timerText(){return`${Math.floor(state.timerLeft/60)}:${String(state.timerLeft%60).padStart(2,'0')}`;}
function pauseTimer(){clearInterval(timerId);timerId=null;}
function syncTimer(){pauseTimer();if(!timerWanted()||modalRoot.innerHTML||timerPaused||document.hidden)return;timerId=setInterval(()=>{state.timerLeft=Math.max(0,state.timerLeft-1);const el=document.getElementById('timer-value');if(el)el.textContent=timerText();if(state.timerLeft===0){pauseTimer();timerPaused=true;save();openModal('Take a breath. Keep thinking.',`<p>The optional team timer has finished. Your progress is safe. The story clock stays at 23:52 while you work out the route.</p><div class="button-row"><button class="button primary" data-action="disable-timer">Continue without a timer</button><button class="button" data-action="restart-timer">Try two more minutes</button></div>`,{kicker:'No work has been lost',kind:'timer'});}},1000);}
function handleAction(button,event){const a=button.dataset.action,idx=Number(button.dataset.index),id=button.dataset.id,p=progress();switch(a){
 case'enter':state.started=true;screen=state.completed?'ending':'game';save();closeModal();resetDraft();if(state.settings.sound)startAmbient();render();window.scrollTo({top:0});break;
 case'home':screen='home';closeModal();render();window.scrollTo({top:0});break;
 case'how':openHow();break;case'how-enter':closeModal();if(screen==='home'){state.started=true;screen=state.completed?'ending':'game';save();render();window.scrollTo({top:0});}break;
 case'sound':toggleSound();break;case'settings':openSettings();break;case'teacher':openTeacher();break;case'glossary':openGlossary();break;case'russian-help':openRussianHelp();break;
 case'close-modal':closeModal();break;case'backdrop':if(event.target===button)closeModal();break;
 case'hotspot':openHotspot(idx);break;case'empty-scene':toast('Look for useful objects or diamond markers. You can reveal clue outlines below.');break;
 case'reveal':p.revealed=!p.revealed;save();render();break;
 case'start-lock':if(p.found.length===current().hotspots.length){p.phase='tasks';resetDraft();save();render();scrollPanel();}break;
 case'choice':selected=button.dataset.value;feedback='';render();break;
 case'word':if(!order.includes(idx)){order.push(idx);feedback='';render();}break;
 case'remove-word':order=order.filter(i=>i!==idx);render();break;
 case'next-task':nextTask();break;case'check-answer':checkTask();break;case'save-production':submitProduction();break;
 case'hint':{const t=current().tasks[p.task];if(!p.hints.includes(t.id))p.hints.push(t.id);hintOpen=!hintOpen;save();render();break;}
 case'model-task':{const t=current().tasks[p.task];if(!p.assisted.includes(t.id))p.assisted.push(t.id);p.answers[t.id]=Array.isArray(t.answer)?t.answer[0]:t.answer;save();render();break;}
 case'finish-production':finishProduction();break;case'next-chapter':nextChapter();break;
 case'chapter':if(idx===0||state.progress[idx-1]?.finished||state.progress[idx]?.finished){state.chapter=idx;screen='game';resetDraft();save();render();window.scrollTo({top:0});}break;
 case'item':openItem(id);break;case'casebook':openCasebook();break;case'case-tab':openCasebook(id);break;case'chapter-evidence':openChapterEvidence();break;
 case'case-doc':openDocument(Number(button.dataset.chapter),idx);break;
 case'setting':if(Object.hasOwn(state.settings,id)){state.settings[id]=!state.settings[id];if(id==='timer'){state.timerLeft=120;timerPaused=false;}save();applySettings();openSettings();render();}break;
 case'export':exportProgress();break;case'import':document.getElementById('import-file')?.click();break;case'new':confirmNew();break;
 case'confirm-new':practiceSnapshot=null;stopAmbient();state=freshState();state.started=true;screen='game';resetDraft();save();closeModal();render();window.scrollTo({top:0});break;
 case'practice':enterPractice(idx);break;case'exit-practice':exitPractice();break;
 case'unlock-safe':if(current().special==='safe'&&p.phase==='safe'&&p.special===0&&state.inventory.includes('key')){p.special=1;sfx('clue');save();render();}break;
 case'take-clapper':if(current().special==='safe'&&p.phase==='safe'&&p.special===1){p.special=2;grant(['clapper','invitation']);sfx('chapter');save();render();toast('The original clapper and invitation draft are in your casebook.');}break;
 case'close-special':if(p.phase==='safe'&&p.special===2){completeChapter();render();scrollPanel();}break;
 case'fit-clapper':if(current().special==='bell'&&p.phase==='bell'&&p.special===0&&state.inventory.includes('clapper')){p.special=1;sfx('clue');save();render();toast('The clapper is secure. It is 23:59.');}else if(current().special==='bell'&&!state.inventory.includes('clapper'))toast('You need the original clapper from chapter 7.');break;
 case'ring':ringBell();break;case'debrief':openDebrief();break;
 case'pause-timer':timerPaused=!timerPaused;render();break;case'disable-timer':state.settings.timer=false;timerPaused=false;save();closeModal();render();break;
 case'restart-timer':state.timerLeft=120;timerPaused=false;save();closeModal();render();break;
 }}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;if(b.tagName==='BUTTON')event.preventDefault();handleAction(b,event);});
document.addEventListener('submit',event=>{if(event.target.id==='task-form'){event.preventDefault();checkTask();}else if(event.target.id==='production-form'){event.preventDefault();submitProduction();}});
document.addEventListener('input',event=>{if(event.target.id!=='answer-input')return;selected=event.target.value;clearTimeout(inputCheckTimer);if(screen!=='game'||progress().phase!=='tasks')return;const t=current().tasks[progress().task],value=selected,snapshot=state,chapter=state.chapter,taskIndex=progress().task;if(t.type==='input'&&accepts(t,value)&&!Object.hasOwn(progress().answers,t.id))inputCheckTimer=setTimeout(()=>{if(state===snapshot&&screen==='game'&&state.chapter===chapter&&progress().phase==='tasks'&&progress().task===taskIndex&&document.getElementById('answer-input')?.value===value)checkTask(value);},450);});
document.addEventListener('change',async event=>{if(event.target.id!=='import-file')return;const file=event.target.files[0];if(!file)return;if(file.size>1000000){toast('This save file is too large. Choose a Midnight Feast JSON export.');return;}try{const imported=validateSave(JSON.parse(await file.text()));practiceSnapshot=null;state=imported;state.settings.sound=false;stopAmbient();screen=state.completed?'ending':'game';resetDraft();save();closeModal();render();toast('Progress imported. Your investigation is ready.');}catch(err){toast('Could not import this file. Choose a valid Midnight Feast save.');}});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.id==='answer-input'&&!event.isComposing){event.preventDefault();if(Object.hasOwn(progress().answers,current().tasks[progress().task].id))nextTask();else checkTask();return;}if(event.key==='Escape'&&modalRoot.innerHTML){closeModal();return;}if(event.key==='Tab'&&modalRoot.innerHTML){const els=[...modalRoot.querySelectorAll('button:not(:disabled),a[href],input:not([type=hidden]),textarea,summary,[tabindex="0"]')].filter(e=>e.getClientRects().length);const first=els[0],last=els.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===modalRoot.querySelector('.modal'))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseTimer();audioCtx?.suspend();save();}else{if(state.settings.sound&&ambient.length)audioCtx?.resume();syncTimer();}});
window.addEventListener('beforeunload',()=>{save();pauseTimer();});
window.FeastLogic={normalize:norm,accepts,validateSave,freshState,shuffle};
render();
})();
